// ============================================================
// MineraAI → ComfyUI RunPod — FÁBRICA DE IMAGENS
// Recebe prompts do MineraAI (produto + prompts extras + roteiro)
// ============================================================
const job = $input.first().json.body || $input.first().json;
const product = job.product || 'produto';
const style = job.style || 'produto';
const prompts = job.prompts || [];
const roteiro = job.roteiro || {};

const STYLE_PREFIX = {
  ugc: 'foto amadora UGC, luz natural, iPhone, casa real, autêntico, ', 
  dark: 'dark aesthetic, moody, cinematic, misterioso, ', 
  cinematic: 'cinematic lighting, 8k, ultra detailed, professional, ', 
  produto: 'product photography, studio lighting, commercial, high detail, sharp focus, ', 
  anime: 'anime style, vibrant, detailed illustration, '
};
const prefix = STYLE_PREFIX[style] || STYLE_PREFIX.produto;

let promptList = [];
if (prompts.length) {
  promptList = prompts.slice(0,4);
} else if (roteiro.cenas && roteiro.cenas.length) {
  promptList = roteiro.cenas.map(c => `${prefix}${c.prompt || c.descricao || ''}, ${product}, 9:16 vertical, alta qualidade`);
} else {
  const base = job.prompt || product;
  promptList = [
    `${prefix}${base}, close-up produto, 9:16 vertical`,
    `${prefix}${base}, lifestyle cozinha real, mão segurando, 9:16`,
    `${prefix}${base}, flat lay mesa, organização, 9:16`
  ];
}

// Garante 1-4 prompts
promptList = promptList.slice(0,4).map(p => p.slice(0,1200));
const batchSize = promptList.length;

// Monta 1 workflow com batch ou múltiplos KSamplers? Aqui usamos batch_size = N com 1 KSampler para simplicidade
// Para prompts diferentes por imagem, criamos múltiplos CLIPTextEncode + KSampler
const seedBase = Math.floor(Math.random()*1e12);
const workflow = {};

// Loader
workflow['1'] = { class_type: 'CheckpointLoaderSimple', inputs: { ckpt_name: 'sd_xl_base_1.0.safetensors' } };
workflow['2'] = { class_type: 'EmptyLatentImage', inputs: { width: 768, height: 1344, batch_size: 1 } };
workflow['7'] = { class_type: 'CLIPTextEncode', inputs: { text: "low quality, blurry, watermark, logo, text, deformed, extra limbs, cartoon, drawing, bad anatomy", clip: ['1',1] } };

// Para cada prompt, cria encode + sampler + decode + save
promptList.forEach((p, idx) => {
  const idBase = 10 + idx*10;
  workflow[`${idBase}`] = { class_type: 'CLIPTextEncode', inputs: { text: p, clip: ['1',1] } };
  workflow[`${idBase+1}`] = { class_type: 'KSampler', inputs: { seed: seedBase+idx, steps: 28, cfg: 7.5, sampler_name: 'dpmpp_2m', scheduler: 'karras', denoise: 1, model: ['1',0], positive: [`${idBase}`,0], negative: ['7',0], latent_image: ['2',0] } };
  workflow[`${idBase+2}`] = { class_type: 'VAEDecode', inputs: { samples: [`${idBase+1}`,0], vae: ['1',2] } };
  workflow[`${idBase+3}`] = { class_type: 'SaveImage', inputs: { filename_prefix: `mineraai/imagem_${job.job_id}_${idx}`, images: [`${idBase+2}`,0] } };
});

return [{ json: { job_id: job.job_id, callback_url: job.callback_url, token: job.token, product, prompts: promptList, batchSize, input: { workflow } } }];

// Extrai imagens do output RunPod
const r = $input.first().json;
const out = r.output || {};
let images = [];
let job = $('Montar Workflow Imagem').first().json;

if (Array.isArray(out)) {
  images = out.map((item, idx) => typeof item === 'string' ? { url: item, prompt: job.prompts[idx] || '', cena: `imagem_${idx}` } : { url: item.url || item.filename || '', prompt: job.prompts[idx] || '' });
} else if (out.images) {
  const arr = Array.isArray(out.images) ? out.images : [out.images];
  images = arr.map((img, idx) => typeof img === 'string' ? { url: img, prompt: job.prompts[idx] || '' } : { url: img.url || img.filename || JSON.stringify(img).slice(0,200), prompt: job.prompts[idx] || '' });
} else if (out.url) {
  images = [{ url: out.url, prompt: job.prompts[0] || '' }];
} else if (typeof out === 'object') {
  // tenta encontrar qualquer URL
  const str = JSON.stringify(out);
  const urls = str.match(/https?:\/\/[^"\s]+\.(png|jpg|jpeg|webp)/g);
  if (urls) images = urls.map((u, idx) => ({ url: u, prompt: job.prompts[idx] || '' }));
}

// fallback: se RunPod retorna base64 ou filename, mantém
if (!images.length && out.message) {
  images = [{ url: out.message, prompt: job.prompts[0] || '' }];
}

return [{ json: { job_id: job.job_id, callback_url: job.callback_url, token: job.token, images, video_url: '', cost_usd: r.cost || null } }];
